import {nodes,edges,buildings,places,shadows,sun,route} from './engine.mjs';
const $=id=>document.getElementById(id),svgNS='http://www.w3.org/2000/svg';
const state={mode:'walk',kind:'balanced',showShade:true,zoom:1};
function el(tag,attrs,parent){const e=document.createElementNS(svgNS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));parent.append(e);return e;}
for(const [name,id]of places){for(const select of [$('origin'),$('destination')]){const o=document.createElement('option');o.value=id;o.textContent=name;select.append(o);}}
$('origin').value=55;$('destination').value=8;
const today=new Date();$('date').value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
for(const e of edges){const a=nodes[e.a],b=nodes[e.b];el('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:'#fafbf7','stroke-width':e.walkOnly?10:20,'stroke-linecap':'round'},$('roads'));if(e.walkOnly)el('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:'#bfd0b3','stroke-width':2,'stroke-dasharray':'4 5'},$('roads'));}
for(const b of buildings){el('rect',{x:b.x,y:b.y,width:b.w,height:b.h,rx:3,fill:'#dddfd4',stroke:'#d0d3c5','stroke-width':1},$('buildings'));el('line',{x1:b.x+5,y1:b.y+5,x2:b.x+b.w-5,y2:b.y+5,stroke:'#eceee4','stroke-width':2},$('buildings'));}
for(const [text,x,y,size]of [['서울숲',852,143,22],['SEOUL FOREST',852,166,8],['성수동',428,348,20],['SEONGSU',428,370,8],['연무장길',530,466,10],['성수이로',214,420,10],['왕십리로',533,62,10]]){const t=el('text',{x,y,'font-size':size,fill:'#9da68f','text-anchor':'middle','letter-spacing':size>15?4:1},$('labels'));t.textContent=text;}
function formatTime(v){return `${String(Math.floor(v/60)%24).padStart(2,'0')}:${String(Math.round(v%60)).padStart(2,'0')}`;}
let results=[];
function compute(){if(!$('date').value){$('date').reportValidity();return;}const time=+$('time').value,date=$('date').value;const s=sun(date,time);$('time-output').textContent=formatTime(time);$('sun-symbol').textContent=s.up>0?'☀':'☾';$('solar-label').textContent=s.up>0?`태양 고도 ${Math.round(s.altitude)}° · 서울 기준 근사치`:'야간 · 직사광선 없음';$('shadows').replaceChildren();if(state.showShade)for(const p of shadows(date,time))el('polygon',{points:p.map(p=>p.join(',')).join(' '),fill:'#7d8d71',opacity:.30},$('shadows'));results=['balanced','shade','fast'].map(kind=>route({start:+$('origin').value,end:+$('destination').value,date,time,mode:state.mode,kind}));render();}
function render(){const selected=results.find(r=>r.kind===state.kind),titles={balanced:'균형 경로',shade:'그늘 우선',fast:'최단 경로'};$('routes').replaceChildren();for(const r of results){const btn=document.createElement('button');btn.className='route-card'+(r.kind===state.kind?' selected':'');btn.setAttribute('aria-pressed',r.kind===state.kind);btn.innerHTML=`<div class="card-top"><span class="radio"></span>${titles[r.kind]}<span class="badge">${{balanced:'적당한 거리, 편안한 길',shade:'햇빛 노출을 줄여요',fast:'거리 우선'}[r.kind]}</span></div><div class="card-stats"><b>${Math.ceil(r.minutes)}<small>분</small></b><span class="distance">· ${(r.length/1000).toFixed(1)} km</span><span class="shade-stat">그늘 <strong>${Math.round(r.shade*100)}%</strong></span></div><div class="shade-bar"><span style="width:${r.shade*100}%"></span></div><div class="card-bottom"><span>햇빛 노출 약 ${Math.round(r.sunMinutes)}분</span><span>${formatTime(+$('time').value+Math.ceil(r.minutes))} 도착 예상</span></div>`;btn.onclick=()=>{state.kind=r.kind;render();};$('routes').append(btn);}
$('route-lines').replaceChildren();for(const r of [...results.filter(r=>r.kind!==state.kind),selected])el('polyline',{points:r.path.map(i=>`${nodes[i].x},${nodes[i].y}`).join(' '),fill:'none',stroke:r.kind===state.kind?'#476c40':'#b9c2ac','stroke-width':r.kind===state.kind?7:4,'stroke-linejoin':'round','stroke-linecap':'round',opacity:r.kind===state.kind?1:.65},$('route-lines'));
$('pins').replaceChildren();for(const [id,label,color]of [[+$('origin').value,'출발','#fff'],[+$('destination').value,'도착','#345539']]){const n=nodes[id];el('circle',{cx:n.x,cy:n.y,r:12,fill:color,stroke:'#345539','stroke-width':4},$('pins'));el('rect',{x:n.x-25,y:n.y-46,width:50,height:25,rx:7,fill:'#fff'},$('pins'));const t=el('text',{x:n.x,y:n.y-29,fill:'#345539','font-size':11,'text-anchor':'middle'},$('pins'));t.textContent=label;}
const delta=results.find(r=>r.kind==='fast').sunMinutes-selected.sunMinutes;$('insight').textContent=selected.length===0?'출발지와 도착지가 같아요':sun($('date').value,+$('time').value).up<=0?'해가 진 시간에는 직사광선이 없어요':delta>.4?`최단 경로보다 햇빛 노출 약 ${Math.round(delta)}분 감소`:`전체 경로 중 약 ${Math.round(selected.shade*100)}%가 그늘이에요`;$('insight-sub').textContent=selected.length===0?'다른 도착지를 선택해 경로를 찾아보세요.':'각 구간의 예상 통과 시각을 반영한 시뮬레이션';}
for(const mode of ['walk','bike'])$(mode).onclick=()=>{state.mode=mode;for(const m of ['walk','bike']){$(m).classList.toggle('active',m===mode);$(m).setAttribute('aria-pressed',m===mode);}compute();};
$('swap').onclick=()=>{const v=$('origin').value;$('origin').value=$('destination').value;$('destination').value=v;compute();};
let timer;$('time').oninput=()=>{clearTimeout(timer);timer=setTimeout(compute,60);};for(const id of ['date','origin','destination'])$(id).onchange=compute;$('search').onclick=compute;
$('layer').onclick=()=>{state.showShade=!state.showShade;$('layer').classList.toggle('active',state.showShade);$('layer').setAttribute('aria-pressed',state.showShade);compute();};
function zoom(d){state.zoom=d===0?1:Math.min(2,Math.max(.8,state.zoom+d));$('viewport').setAttribute('transform',`translate(${500*(1-state.zoom)},${380*(1-state.zoom)}) scale(${state.zoom})`);}$('zoom-in').onclick=()=>zoom(.2);$('zoom-out').onclick=()=>zoom(-.2);$('reset').onclick=()=>zoom(0);$('about').onclick=()=>$('help').showModal();$('close-help').onclick=()=>$('help').close();compute();
